Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>

unsigned sum(unsigned n) {
 if (n == 0) { return 0; }
 return n + sum(n - 1);
}
int main(void) {
 unsigned n = 4;
 if (n > 10) { puts("rejected"); return 0; }
 printf("%u\n", sum(n));
}
```

